with lines as (select id, host, level, status_code, key, value from app_logs lateral view explode(context) x as key, value) select id, status_code, key, stddev_samp(status_code) over (partition by level, host) as level_stddev_samp_status_code, max(status_code) over (partition by level) as level_max_status_code, ntile(3) over (order by status_code, id, key) as status_code_bucket, avg(status_code) over (partition by level) as level_avg_status_code, sum(status_code) over (partition by key, host order by status_code, id, key rows between unbounded preceding and current row) as cumulative_status_code from lines
